Promise.all([
      fetchCtsvStats().catch(() => ({ stats: MOCK_STATS })),
      fetchCtsvEvents().catch(() => ({ events: MOCK_EVENTS })),
      fetchCtsvPartners({ status: 'pending' }).catch(() => ({ partners: [] }))
    ])
      .then(([statsRes, eventsRes, partnersRes]) => {
        if (cancelled) return;
        setStats(statsRes.stats?.length ? statsRes.stats : MOCK_STATS);
        const list = eventsRes.events?.length ? eventsRes.events : MOCK_EVENTS;
        setEvents(list);
        setPendingPartners((partnersRes.partners || []).slice(0, 4));
      })
      .finally

fetchCtsvEvent(editEventId)
      .then((data) => {
        const event = data.event;
        if (!canCtsvEditSchoolEvent(event)) {
          showToast?.('Sự kiện không thể chỉnh sửa ở trạng thái hiện tại.', 'error');
          navigate(`/ctsv/events/${editEventId}`);
          return;
        }
        setForm(mapEventToForm(event));
        setTickets(mapEventToTickets(event));
        setSpeakers(mapEventToSpeakers(event));
        setBannerFileName(event.bannerFileName || '');
      })
      .catch((err) => {
        showToast?.(err.message || 'Không tải được sự kiện.', 'error');
        navigate('/ctsv/events');
      })
      .finally

